void send_all(SOCKET s,const uint8_t* data,size_t n){while(n){int count=send(s,reinterpret_cast<const char*>(data),int(std::min(n,size_t(65536))),0);require(count>0,"Socket send failed");data+=count;n-=size_t(count);}}
Service::Service(std::string n,int p):name(std::move(n)),port(p){}Service::~Service(){stop();}
static SOCKET bind_socket(int port,int type){SOCKET s=socket(AF_INET,type,0);require(s!=INVALID_SOCKET,"Cannot create socket");BOOL exclusive=TRUE;setsockopt(s,SOL_SOCKET,SO_EXCLUSIVEADDRUSE,reinterpret_cast<char*>(&exclusive),sizeof(exclusive));sockaddr_in a{};a.sin_family=AF_INET;a.sin_port=htons(uint16_t(port));a.sin_addr.s_addr=htonl(INADDR_LOOPBACK);if(bind(s,reinterpret_cast<sockaddr*>(&a),sizeof(a))==SOCKET_ERROR){int error=WSAGetLastError();closesocket(s);throw std::runtime_error("Loopback port "+std::to_string(port)+" unavailable: "+std::to_string(error));}return s;}
void Service::start_tcp(const std::function<void(SOCKET)>& handler){if(running)return;try{listener=bind_socket(port,SOCK_STREAM);require(listen(listener,16)==0,"Listen failed");running=true;error.clear();thread=std::thread([this,handler]{while(running){SOCKET client=accept(listener,nullptr,nullptr);if(client==INVALID_SOCKET)break;DWORD timeout=30000;setsockopt(client,SOL_SOCKET,SO_RCVTIMEO,reinterpret_cast<char*>(&timeout),sizeof(timeout));std::lock_guard lock(sockets_mutex);if(clients.size()>=64){closesocket(client);continue;}clients.push_back(client);workers.emplace_back([this,handler,client]{try{handler(client);}catch(const std::exception& e){error=e.what();}shutdown(client,SD_BOTH);closesocket(client);std::lock_guard guard(sockets_mutex);auto it=std::find(clients.begin(),clients.end(),client);if(it!=clients.end())clients.erase(it);});}});}catch(const std::exception& e){error=e.what();if(listener!=INVALID_SOCKET)closesocket(listener);listener=INVALID_SOCKET;throw;}}
void Service::start_udp(const std::function<Bytes(const Bytes&,const sockaddr_in&,SOCKET)>& handler){if(running)return;try{listener=bind_socket(port,SOCK_DGRAM);running=true;error.clear();thread=std::thread([this,handler]{std::array<uint8_t,65535> buf;while(running){sockaddr_in peer{};int len=sizeof(peer);int n=recvfrom(listener,reinterpret_cast<char*>(buf.data()),int(buf.size()),0,reinterpret_cast<sockaddr*>(&peer),&len);if(n<=0){if(running)error="UDP receive failed: "+std::to_string(WSAGetLastError());break;}try{handler(Bytes(buf.begin(),buf.begin()+n),peer,listener);}catch(const std::exception& e){error=e.what();}}});}catch(const std::exception& e){error=e.what();throw;}}
void Service::stop(){running=false;if(listener!=INVALID_SOCKET){shutdown(listener,SD_BOTH);closesocket(listener);listener=INVALID_SOCKET;}{std::lock_guard lock(sockets_mutex);for(auto s:clients)shutdown(s,SD_BOTH);}if(thread.joinable())thread.join();for(auto& w:workers)if(w.joinable())w.join();workers.clear();clients.clear();}Json Service::state()const{return {{"name",name},{"port",port},{"running",running.load()},{"status",running?"running":error.empty()?"stopped":"error"},{"error",error}};}
Store::Store(const fs::path& path){fs::create_directories(path.parent_path());require(sqlite3_open(path.string().c_str(),&db)==SQLITE_OK,"Cannot open C++ database");execute("PRAGMA journal_mode=WAL");execute("CREATE TABLE IF NOT EXISTS packets(id INTEGER PRIMARY KEY,ts REAL,channel TEXT,direction TEXT,kind TEXT,hex TEXT,decoded TEXT,label TEXT DEFAULT '',annotation TEXT DEFAULT '',confidence TEXT DEFAULT 'observed')");execute("CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,ts REAL,kind TEXT,detail TEXT)");recorded_packets=query("SELECT COUNT(*) count FROM packets")[0].at("count").get<uint64_t>();}Store::~Store(){sqlite3_close(db);}void Store::execute(const std::string& sql){std::lock_guard lock(mutex);char* error=nullptr;int code=sqlite3_exec(db,sql.c_str(),nullptr,nullptr,&error);if(code!=SQLITE_OK){std::string reason=error?error:"sqlite failure";sqlite3_free(error);throw std::runtime_error(reason);}}
Json Store::query(const std::string& sql){std::lock_guard lock(mutex);sqlite3_stmt* stmt=nullptr;require(sqlite3_prepare_v2(db,sql.c_str(),-1,&stmt,nullptr)==SQLITE_OK,sqlite3_errmsg(db));Json result=Json::array();while(sqlite3_step(stmt)==SQLITE_ROW){Json row;for(int i=0;i<sqlite3_column_count(stmt);i++){std::string key=sqlite3_column_name(stmt,i);switch(sqlite3_column_type(stmt,i)){case SQLITE_INTEGER:row[key]=sqlite3_column_int64(stmt,i);break;case SQLITE_FLOAT:row[key]=sqlite3_column_double(stmt,i);break;case SQLITE_NULL:row[key]=nullptr;break;default:row[key]=reinterpret_cast<const char*>(sqlite3_column_text(stmt,i));}}result.push_back(row);}sqlite3_finalize(stmt);return result;}
uint64_t Store::packet_count(){std::lock_guard lock(mutex);return recorded_packets;}
void Store::packet(const std::string& channel,const std::string& direction,const Bytes& data,const Json& decoded){std::lock_guard lock(mutex);sqlite3_stmt* s=nullptr;sqlite3_prepare_v2(db,"INSERT INTO packets(ts,channel,direction,kind,hex,decoded) VALUES(?,?,?,?,?,?)",-1,&s,nullptr);auto kind=decoded.value("kind",decoded.value("message_type_name","unknown")),raw=hex(data),j=decoded.dump();sqlite3_bind_double(s,1,wall_time());sqlite3_bind_text(s,2,channel.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,3,direction.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,4,kind.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,5,raw.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,6,j.c_str(),-1,SQLITE_TRANSIENT);int result=sqlite3_step(s);sqlite3_finalize(s);require(result==SQLITE_DONE,"Packet persistence failed");++recorded_packets;}
void Store::event(const std::string& kind,const Json& detail){std::lock_guard lock(mutex);sqlite3_stmt* s=nullptr;sqlite3_prepare_v2(db,"INSERT INTO events(ts,kind,detail) VALUES(?,?,?)",-1,&s,nullptr);auto j=detail.dump();sqlite3_bind_double(s,1,wall_time());sqlite3_bind_text(s,2,kind.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,3,j.c_str(),-1,SQLITE_TRANSIENT);sqlite3_step(s);sqlite3_finalize(s);}
Backend::Backend(fs::path p,Json settings):root(std::move(p)),config(std::move(settings)),contracts(root/"config/contracts.json"),store(root/"data/lab.sqlite"),protocol([this](auto& k,auto& d){event(k,d);}),geometry(std::make_shared<CollisionWorld>()),lobby(*this,contracts),world("world",config.at("world_port")),lobby_service("lobby",config.at("lobby_port")),tether("tether",config.at("tether_port")),http("dashboard",config.at("dashboard_port")){if(fs::exists(root/"data/movement-settings.json"))movement_settings=MovementSettings::from(read_json(root/"data/movement-settings.json"));try{geometry->load(root/config.at("terrain_manifest").get<std::string>(),root/config.at("collision_cache").get<std::string>(),config.contains("terrain_mesh_manifest")?root/config.at("terrain_mesh_manifest").get<std::string>():fs::path{});}catch(const std::exception& e){geometry_error=e.what();event("geometry_error",{{"reason",e.what()}});}if(config.value("initialize_winstead_floor",false)){try{double started=mono_time();prepare_winstead_collision(*this,geometry);event("winstead_collision_preloaded",{{"duration_ms",(mono_time()-started)*1000.},{"private_tiles",winstead_geometry->tiles.size()}});}catch(const std::exception& e){event("winstead_collision_preload_failed",{{"reason",e.what()}});}}event("backend_ready",{{"ports",{{"dashboard",http.port},{"world",world.port},{"lobby",lobby_service.port},{"tether",tether.port}}},{"geometry",geometry->statistics()}});protocol.resolve_character=[this](const Json& login)->Json{
 std::string url=login.value("url","");const std::string marker="EncryptionToken=";auto start=url.find(marker);
 // Protocol-only test peers may omit a lobby token; native initialization still requires a selected character.
 if(start==std::string::npos)return Json();start+=marker.size();auto end=url.find_first_of("&?",start);auto token=url.substr(start,end==std::string::npos?end:end-start);
 auto found=lobby.tokens.find(token);if(found==lobby.tokens.end()||found->second.second<mono_time())return {{"error","Character connection token expired or unknown"}};
 auto id=found->second.first;auto character=std::find_if(lobby.characters.begin(),lobby.characters.end(),[&](const Json& row){return row.at("character_id")==id;});
 if(character==lobby.characters.end())return {{"error","Selected character no longer exists"}};Json selected={{"character_id",id},{"character_name",character->at("character_name")}};lobby.tokens.erase(found);return selected;
 };initialization_thread=std::thread([this]{initialize_clients();});}
Backend::~Backend(){stopping=true;if(initialization_thread.joinable())initialization_thread.join();http.stop();tether.stop();lobby_service.stop();world.stop();}
void Backend::event(const std::string& kind,const Json& detail){std::lock_guard lock(mutex);store.event(kind,detail);std::string service=detail.value("service",kind.starts_with("udp")||kind=="join"||kind=="welcome"?"world":kind.starts_with("tether")?"tether":kind.starts_with("lobby")?"lobby":"dashboard");Json entry={{"ts",wall_time()},{"kind",kind},{"detail",detail}};if(!service_logs.contains(service))service_logs[service]=Json::array();auto& log=service_logs[service];log.push_back(entry);if(log.size()>200)log.erase(log.begin());std::ofstream f(root/"logs"/(service+".jsonl"),std::ios::app);f<<entry.dump()<<'\n';}
void Backend::record(const std::string& channel,const std::string& direction,const Bytes& data,const Json& decoded){store.packet(channel,direction,data,decoded);}
void Backend::start_service(const std::string& n){if(n=="world")world.start_udp([this](auto& b,auto& p,SOCKET s){world_packet(b,p,s);return Bytes{};});else if(n=="lobby")lobby_service.start_tcp([this](SOCKET s){lobby.serve(s);});else if(n=="tether"){if(!lobby_service.running)start_service("lobby");tether.start_udp([this](auto& b,auto& p,SOCKET s){tether_packet(b,p,s);return Bytes{};});}else throw std::runtime_error("Unknown service");event("service_started",{{"service",n}});}
void Backend::stop_service(const std::string& n){if(n=="tether")tether.stop();else if(n=="lobby"){tether.stop();lobby_service.stop();}else if(n=="world"){world.stop();std::lock_guard lock(mutex);protocol.connections.clear();players.clear();trails.clear();corrections.clear();}else throw std::runtime_error("Unknown service");event("service_stopped",{{"service",n}});}
void Backend::world_packet(const Bytes& data,const sockaddr_in& peer,SOCKET socket){double received_at=mono_time();std::lock_guard lock(mutex);double processing_at=mono_time();double packet_world_time=std::floor((processing_at-world_clock_origin)*60.)/60.;char host[INET_ADDRSTRLEN];inet_ntop(AF_INET,&peer.sin_addr,host,sizeof(host));uint16_t port=ntohs(peer.sin_port);std::string key=std::string(host)+":"+std::to_string(port);auto decoded=decode_packet(data);record("world","C2S",data,decoded);auto responses=protocol.handle(data,host,port);auto it=protocol.connections.find(key);if(it!=protocol.connections.end()&&it->second.phase=="joined"&&decoded.contains("bunches")){auto& c=it->second;for(auto& b:decoded["bunches"]){if(b.value("partial",false)||b.value("exports",false)||b.value("must_map",false)||b.value("open",false)||b.value("close",false))continue;try{if(b["channel"]==3&&c.ack_field>=0&&c.actors.contains("pawn")){auto fields=decode_actor_rpc(unhex(b["payload_hex"]),b.at("payload_bits"),c.controller_max);for(auto& f:fields)if(f["field_index"]==c.ack_field){BitReader arg(unhex(f["argument_hex"]),f.at("argument_bits"));if(arg.read(1)){Guid g{arg.read(64),uint32_t(arg.read(32)),uint32_t(arg.read(32))};if(g==c.actors.at("pawn")&&arg.remaining()==0){c.possession=true;event("possession_acknowledged",{{"connection_id",c.id},{"pawn_guid",g.json()}});}}}}else if(b["channel"]==9&&c.possession&&c.stages.contains("ActivateMovement")&&players.contains(c.id)){auto fields=decode_actor_rpc(unhex(b["payload_hex"]),b.at("payload_bits"),198);for(auto& f:fields)if(f["field_index"]==44){auto moves=decode_move_argument(unhex(f["argument_hex"]),f.at("argument_bits"));double newest=moves[0].at("timestamp");auto sorted=movement_processing_order(moves);auto state=players.at(c.id);for(auto& move:sorted){double simulation_started=mono_time();auto result=state->advance(move,state->timing.enabled?packet_world_time:mono_time());if(!result)continue;(*result)["simulation_ms"]=(mono_time()-simulation_started)*1000.;(*result)["packet_lock_wait_ms"]=(processing_at-received_at)*1000.;(*result)["packet_processing_elapsed_ms"]=(mono_time()-processing_at)*1000.;if(move.at("kind")=="new"){auto client_position=move.at("client_location").get<Vec>();double error=length(sub(client_position,state->position));bool matching=movement_matches(error,move.at("movement_mode")==state->mode,c.speed_synced==state->speed,result->contains("discarded_time")||result->value("force_correction",false));auto& policy=corrections[c.id];double now=mono_time();bool send_response=matching||policy.allow(now,error,move.at("movement_mode")!=state->mode,result->contains("discarded_time"));if(send_response){auto correction=matching?move_ack(float(newest)):move_correction(float(newest),state->position,state->velocity,state->mode);Json response=Json::array({{{"channel",9},{"channel_name",102},{"reliable",false},{"payload_hex",hex(correction.data)},{"payload_bits",correction.bits}}});responses.push_back(protocol.send(c,response));if(!matching)policy.last_sent=now;}(*result)["response"]=matching?"ack":send_response?"correction":"deferred";(*result)["prediction_error_cm"]=error;(*result)["prediction_error_vector"]=sub(client_position,state->position);(*result)["speed_synchronized"]=c.speed_synced==state->speed;}auto& trail=trails[c.id];if(trail.empty()||length(sub(trail.back(),state->position))>1){trail.push_back(state->position);if(trail.size()>2000)trail.erase(trail.begin());}event("movement",{{"connection_id",c.id},{"result",*result}});}}}}catch(const std::exception& e){event("world_payload_refused",{{"connection_id",c.id},{"reason",e.what()}});}}}for(auto& b:responses){sendto(socket,reinterpret_cast<const char*>(b.data()),int(b.size()),0,reinterpret_cast<const sockaddr*>(&peer),sizeof(peer));record("world","S2C",b,decode_packet(b,true));}}
static uint64_t be(const Bytes& b,size_t offset,int n){require(offset+size_t(n)<=b.size(),"Truncated tether header");uint64_t v=0;for(int i=0;i<n;i++)v=(v<<8)|b[offset+i];return v;}static void be(Bytes& b,uint64_t v,int n){for(int i=n-1;i>=0;i--)b.push_back(uint8_t(v>>(i*8)));}static Bytes tether_header(int kind,uint32_t sid,int fragment,int size,uint64_t seq,uint64_t expected,uint64_t timestamp){Bytes b;be(b,0xa55a0200u|kind,4);be(b,sid,4);be(b,128,4);be(b,fragment,2);be(b,size,2);be(b,seq,8);be(b,expected,8);be(b,timestamp,8);return b;}
void Backend::tether_packet(const Bytes& b,const sockaddr_in& peer,SOCKET socket){struct Client{uint64_t seq=0,expected=0;std::map<uint64_t,std::pair<int,Bytes>> fragments;std::map<uint64_t,std::vector<Bytes>> replies;};static std::map<std::pair<uint16_t,uint32_t>,Client> clients;std::lock_guard lock(mutex);require(b.size()>=40&&(be(b,0,4)>>8)==0xa55a02,"Invalid tether header");int kind=b[3],fragment=int(be(b,12,2)),size=int(be(b,14,2));uint32_t sid=uint32_t(be(b,4,4));uint64_t seq=be(b,16,8),timestamp=be(b,32,8);require(kind>=1&&kind<=5,"Tether kind");require(kind==2||kind==5||b.size()==40+size_t(size),"Tether length");auto& client=clients[{ntohs(peer.sin_port),sid}];Json decoded={{"kind","tether_"+std::to_string(kind)},{"session_id",sid},{"seq",seq},{"fragment",fragment}};record("tether","C2S",b,decoded);std::vector<Bytes> replies;if(kind==5){auto id=random_id();auto response=tether_header(5,sid,0,0,0,0,0);be(response,id.size(),4);response.insert(response.end(),id.begin(),id.end());replies.push_back(response);}else if(kind==3)replies.push_back(tether_header(4,sid,0,0,0,client.expected,0));else if(kind==1){replies.push_back(tether_header(2,sid,0,0,seq,std::max(client.expected,seq+1),timestamp));if(client.replies.contains(seq)){auto& old=client.replies[seq];replies.insert(replies.end(),old.begin(),old.end());}else if(seq>=client.expected){client.fragments[seq]={fragment,Bytes(b.begin()+40,b.end())};if(client.fragments.contains(client.expected)){size_t count=client.fragments[client.expected].first+1;require(count<=128,"Tether fragment budget");Bytes message;bool ready=true;for(size_t i=0;i<count;i++){auto it=client.fragments.find(client.expected+i);if(it==client.fragments.end()){ready=false;break;}require(it->second.first==int(count-1-i),"Tether fragment ordering");message.insert(message.end(),it->second.second.begin(),it->second.second.end());}if(ready){auto m=contracts.decode("ics_tether.TetherMessage",message);for(size_t i=0;i<count;i++)client.fragments.erase(client.expected+i);client.expected+=count;std::string name=m["tags"].value("message_type_name","");if(name=="request_open_session"||name=="request_echo"){if(name=="request_open_session"){auto& tags=m["tags"];tags.update({{"auth_endpoint","http://127.0.0.1:"+std::to_string(lobby_service.port)},{"auth_token","lab-local-auth"},{"refresh_token","lab-local-refresh"},{"auth0_accesstoken","lab-local-account"},{"account_id","00000037000000370000003700000000"},{"eac_deployment_id",""},{"eac_sandbox_id",""},{"grpc_metadata_magic_key","content-md5"},{"grpc_metadata_magic_val","7b7b59b4dc518f6db31c3f928ac86a00"},{"user_agent_prefix","ashes-cpp-lab"}});require(sha256_file(config.at("sdk_path").get<std::string>())==config.at("sdk_sha256").get<std::string>(),"Installed EOS SDK hash mismatch");tags["eac_deployment_id"]="eeeeeeee000000000000000000000001";tags["eac_sandbox_id"]="eeeeeeee000000000000000000000002";event("tether_session",{{"service","tether"}});}auto payload=contracts.encode("ics_tether.TetherMessage",m);size_t chunks=(payload.size()+1359)/1360;std::vector<Bytes> generated;for(size_t i=0;i<chunks;i++){size_t begin=i*1360,end=std::min(payload.size(),begin+1360);auto reply=tether_header(1,sid,int(chunks-1-i),int(end-begin),client.seq++,client.expected,uint64_t(wall_time()*1000));reply.insert(reply.end(),payload.begin()+begin,payload.begin()+end);generated.push_back(reply);}client.replies[seq]=generated;replies.insert(replies.end(),generated.begin(),generated.end());if(client.replies.size()>1024)client.replies.erase(client.replies.begin());}}}}}for(auto& reply:replies){sendto(socket,reinterpret_cast<const char*>(reply.data()),int(reply.size()),0,reinterpret_cast<const sockaddr*>(&peer),sizeof(peer));record("tether","S2C",reply,{{"kind","tether_"+std::to_string(reply[3])}});}}
Json Backend::state(){std::lock_guard lock(mutex);return {{"backend","C++"},{"services",Json::array({lobby_service.state(),tether.state(),world.state(),http.state()})},{"packet_count",store.packet_count()},{"movement_settings",movement_settings.json()},{"online_players",players.size()},{"connections",protocol.connections.size()},{"geometry",geometry->statistics()},{"geometry_error",geometry_error},{"logs",service_logs},{"client",attached},{"client_launch",client_process.state()},{"limitations",Json::array({"Static prop collision coverage is incomplete","Runtime collision export and proof-specific inspection tools are still being ported","Sprint and broader world gameplay remain unverified"})}};}
Json Backend::world_view(){std::lock_guard lock(mutex);Json ps=Json::array();for(auto& [peer,c]:protocol.connections){if(c.phase!="joined"||!players.contains(c.id))continue;auto p=players.at(c.id);ps.push_back({{"id",c.id},{"peer",peer},{"position",p->position},{"velocity",p->velocity},{"movement_settings",MovementSettings{p->speed,p->collision_enabled,p->gravity_enabled}.json()},{"mode",p->mode},{"grounded",p->mode==1},{"radius",p->radius},{"half_height",p->half_height},{"tiles",p->world->tiles.size()},{"colliders",p->world->meshes.size()},{"geometry",p->world->statistics()},{"trail",trails[c.id]},{"time_budget",p->budget},{"movement_comparison",p->comparison()},{"ground_speed_profile",p->ground_speeds.json()}});}return {{"observed_at",wall_time()},{"players",ps},{"online_players",ps.size()},{"geometry",geometry->statistics()}};}
void Backend::send_world(Connection& c,const Json& bs){auto found=std::find_if(protocol.connections.begin(),protocol.connections.end(),[&](auto& p){return &p.second==&c;});require(found!=protocol.connections.end()&&world.running,"World connection disappeared");auto peer=found->first;auto split=peer.find(':');sockaddr_in addr{};addr.sin_family=AF_INET;addr.sin_addr.s_addr=htonl(INADDR_LOOPBACK);addr.sin_port=htons(uint16_t(std::stoul(peer.substr(split+1))));auto packet=protocol.send(c,bs);sendto(world.listener,reinterpret_cast<const char*>(packet.data()),int(packet.size()),0,reinterpret_cast<sockaddr*>(&addr),sizeof(addr));record("world","S2C",packet,decode_packet(packet,true));}
void Backend::inspect(uint32_t pid){auto snapshot=inspect_client(pid,config.at("client_exe").get<std::string>(),config.at("client_sha256"));write_file(root/"data/client-inspection.json",snapshot.dump(2));attached=snapshot.at("client_proof");attached["inspection_errors"]=snapshot.at("errors").size();event("client_inspected",{{"service","dashboard"},{"pid",pid},{"errors",snapshot.at("errors").size()}});}
void Backend::stage(const Json& command){std::lock_guard lock(mutex);std::string id=command.at("connection_id");auto it=std::find_if(protocol.connections.begin(),protocol.connections.end(),[&](auto& p){return p.second.id==id;});require(it!=protocol.connections.end()&&it->second.phase=="joined","Current joined connection required");auto& c=it->second;std::string stage=command.at("stage");if(stage=="bootstrap"){require(attached.contains("pid"),"Inspect exact client process before bootstrap");ProcessReader reader(attached.at("pid"),config.at("client_exe").get<std::string>(),config.at("client_sha256"));require(reader.created==attached.at("process_created_filetime"),"Client lifetime changed");auto packets=protocol.bootstrap(c,config.at("spawn").get<Vec>());sockaddr_in addr{};addr.sin_family=AF_INET;addr.sin_addr.s_addr=htonl(INADDR_LOOPBACK);addr.sin_port=htons(uint16_t(std::stoul(it->first.substr(it->first.find(':')+1))));for(auto& p:packets){sendto(world.listener,reinterpret_cast<const char*>(p.data()),int(p.size()),0,reinterpret_cast<sockaddr*>(&addr),sizeof(addr));record("world","S2C",p,decode_packet(p,true));}event("bootstrap_authored",{{"connection_id",c.id},{"client_acceptance_verified",false}});return;}
// Further stages require an explicit fresh proof manifest. Never reuse frozen live actor identities.
auto proof=read_json(root/"data/client-inspection.json");ProcessReader reader(attached.at("pid"),config.at("client_exe").get<std::string>(),config.at("client_sha256"));verify_evidence(reader.proof(),proof);require(proof.at("errors").empty(),"Clean current actor inspection required");for(auto kind:{"controller","pawn","game_state","player_state"}){require(c.actors.contains(kind),"Authored actor missing");auto matches=std::count_if(proof.at("network_guid_actor_matches").begin(),proof.at("network_guid_actor_matches").end(),[&](auto& m){return m.at("guid")==c.actors.at(kind).json();});require(matches==1,"Unique current accepted actor GUID required");}dispatch_stage(*this,c,proof,stage);}
Json Backend::control(const Json& body){std::string action=body.at("action");if(action=="launch_client"){std::lock_guard lock(mutex);start_service("world");start_service("lobby");start_service("tether");auto result=client_process.start(root,config);event("client_launch",{{"service","dashboard"},{"result",result}});return result;}else if(action=="start_service")start_service(body.at("service"));else if(action=="stop_service")stop_service(body.at("service"));else if(action=="start_services"){start_service("world");start_service("lobby");start_service("tether");}else if(action=="stop_services"){stop_service("tether");stop_service("lobby");stop_service("world");}else if(action=="movement_settings"){
 auto settings=MovementSettings::from(body.at("settings"));std::lock_guard lock(mutex);
 write_file(root/"data/movement-settings.json",settings.json().dump(2));movement_settings=settings;
 for(auto& [id,p]:players)p->configure(settings);for(auto& [peer,c]:protocol.connections){c.speed_synced=0;c.speed_sync_status="Synchronizing client speed";}
 event("movement_settings_changed",{{"settings",settings.json()},{"players",players.size()}});
 return {{"ok",true},{"message","Movement settings applied"},{"movement_settings",settings.json()}};
 }else if(action=="recover_spawn"){
 std::lock_guard lock(mutex);require(world.running&&client_process.process,"Current local client required for recovery");
 std::string id=body.at("connection_id");uint32_t pid=body.at("pid");uint64_t created=body.at("created_filetime");require(pid==client_process.pid,"Recovery client PID mismatch");
 auto connection=std::find_if(protocol.connections.begin(),protocol.connections.end(),[&](auto& entry){return entry.second.id==id;});
 require(connection!=protocol.connections.end()&&connection->second.phase=="joined"&&connection->second.possession&&connection->second.stages.contains("ActivateMovement")&&players.contains(id),"Initialized possessed connection required for recovery");
 auto& c=connection->second;ProcessReader r(pid,config.at("client_exe").get<std::string>(),config.at("client_sha256"));require(r.created==created,"Recovery client lifetime mismatch");Reflection f(r);
 auto snapshot=read_json(root/"data/client-inspection.json");require(snapshot.at("client_proof").at("pid")==pid&&snapshot.at("client_proof").at("process_created_filetime")==created,"Recovery snapshot lifetime mismatch");
 auto actor=[&](const std::string& name,const std::string& cls){uint64_t address=0;for(auto& row:snapshot.at("network_guid_actor_matches"))if(row.at("guid")==c.actors.at(name).json()){require(!address,"Unique recovery actor required");address=std::stoull(row.at("actor").at("address").get<std::string>(),nullptr,16);auto live=f.identity(address,cls);require(live.at("object_index")==row.at("weak_object_index")&&live.at("serial")==row.at("weak_object_serial"),"Recovery actor lifetime changed");bool accepted=false;for(auto& driver:snapshot.at("net_drivers"))if(driver.at("guid_cache")==row.at("guid_cache"))accepted|=f.guid_accepted(std::stoull(driver.at("address").get<std::string>(),nullptr,16),c.actors.at(name),address);require(accepted,"Recovery actor GUID no longer accepted");}require(address,"Recovery actor missing");return address;};
 auto pawn=actor("pawn","PlayerPawn_C"),controller=actor("controller","AoCPlayerControllerBP_C");f.property(pawn,"Controller",0x398,8);f.property(controller,"Pawn",0x3a8,8);f.property(controller,"AcknowledgedPawn",0x428,8);
 require(r.at<uint64_t>(pawn+0x398)==controller&&r.at<uint64_t>(controller+0x3a8)==pawn&&r.at<uint64_t>(controller+0x428)==pawn,"Current mutual possession required for recovery");r.verify_alive();
 auto player=players.at(id);require(player->timestamp.has_value(),"Current accepted move timestamp required for recovery");player->recover_spawn(config.at("spawn").get<Vec>());
 auto correction=move_correction(float(*player->timestamp),player->position,player->velocity,player->mode);send_world(c,Json::array({{{"channel",9},{"channel_name",102},{"reliable",false},{"payload_hex",hex(correction.data)},{"payload_bits",correction.bits}}}));trails[id]={player->position};corrections[id].last_sent=mono_time();
 event("supported_spawn_recovery",{{"connection_id",id},{"pid",pid},{"created_filetime",created},{"position",player->position},{"client_acceptance_requires_readback",true}});
 return {{"ok",true},{"message","Recovery sent to verified supported spawn"},{"position",player->position}};
 }else if(action=="flight_altitude"){
 require(body.at("delta").is_number(),"Numeric altitude step required");double delta=body.at("delta");
 require(std::isfinite(delta)&&std::abs(delta)<=10000,"Altitude step must be within 100 metres");std::lock_guard lock(mutex);
 require(!players.empty(),"Join the game before changing altitude");require(!movement_settings.gravity_enabled,"Enable Fly or disable gravity first");
 for(auto& [peer,c]:protocol.connections){if(!c.possession||!players.contains(c.id))continue;auto p=players.at(c.id);p->change_altitude(delta);
 if(p->timestamp){auto correction=move_correction(float(*p->timestamp),p->position,p->velocity,p->mode);send_world(c,Json::array({{{"channel",9},{"channel_name",102},{"reliable",false},{"payload_hex",hex(correction.data)},{"payload_bits",correction.bits}}}));}
 trails[c.id].push_back(p->position);if(trails[c.id].size()>2000)trails[c.id].erase(trails[c.id].begin());}
 event("flight_altitude",{{"delta",delta}});
 return {{"ok",true},{"message","Flight altitude updated"}};
 }else if(action=="inspect_client")inspect(body.at("pid"));else if(action=="stage")stage(body);else if(action=="admit_winstead_collision")return admit_winstead_collision(*this,body);else if(action=="reload_geometry"){auto cache=std::make_shared<CollisionWorld>();cache->load(root/config.at("terrain_manifest").get<std::string>(),root/config.at("collision_cache").get<std::string>(),config.contains("terrain_mesh_manifest")?root/config.at("terrain_mesh_manifest").get<std::string>():fs::path{});auto prepared=config.value("initialize_winstead_floor",false)?prepare_winstead_collision(*this,cache):std::shared_ptr<CollisionWorld>{};std::lock_guard lock(mutex);geometry=cache;for(auto& [peer,c]:protocol.connections)if(players.contains(c.id))players.at(c.id)->world=c.stages.contains("WinsteadCollisionAdmitted")&&prepared?prepared:cache;geometry_error.clear();event("geometry_reloaded",{{"state_preserved",true},{"geometry",cache->statistics()}});}else throw std::runtime_error("Unknown control action");return {{"ok",true},{"message",action+" completed"}};}
static std::map<std::string,std::string> query_args(const std::string& query){std::map<std::string,std::string> result;std::istringstream s(query);std::string pair;while(std::getline(s,pair,'&')){auto p=pair.find('=');if(p!=std::string::npos)result[pair.substr(0,p)]=pair.substr(p+1);}return result;}
void Backend::serve_http(SOCKET socket){std::string request;std::array<char,8192> b;size_t end;while((end=request.find("\r\n\r\n"))==std::string::npos){int n=recv(socket,b.data(),int(b.size()),0);require(n>0,"HTTP receive failed");request.append(b.data(),n);require(request.size()<=65536,"HTTP header budget");}std::istringstream head(request.substr(0,end));std::string method,target,version;head>>method>>target>>version;std::map<std::string,std::string> headers;std::string line;std::getline(head,line);while(std::getline(head,line)){auto p=line.find(':');if(p==std::string::npos)continue;std::string key=line.substr(0,p),value=line.substr(p+1);std::transform(key.begin(),key.end(),key.begin(),[](unsigned char c){return char(std::tolower(c));});while(!value.empty()&&std::isspace(static_cast<unsigned char>(value.front())))value.erase(value.begin());while(!value.empty()&&std::isspace(static_cast<unsigned char>(value.back())))value.pop_back();headers[key]=value;}std::string payload=request.substr(end+4);int status=200;std::string type="application/json",response;auto split=target.find('?');std::string path=target.substr(0,split);auto q=query_args(split==std::string::npos?"":target.substr(split+1));auto arg=[&](const std::string& key,const std::string& fallback){return q.contains(key)?q[key]:fallback;};try{Json result;if(method=="POST"){std::string local="127.0.0.1:"+std::to_string(http.port),localhost="localhost:"+std::to_string(http.port);require(headers["host"]==local||headers["host"]==localhost,"Invalid local Host");if(headers.contains("origin"))require(headers["origin"]=="http://"+local||headers["origin"]=="http://"+localhost,"Invalid dashboard Origin");size_t n=std::stoul(headers.at("content-length"));require(n>0&&n<=65536,"HTTP body budget");while(payload.size()<n){int count=recv(socket,b.data(),int(b.size()),0);require(count>0,"Truncated HTTP body");payload.append(b.data(),count);}auto body=Json::parse(payload.substr(0,n));if(path=="/api/control")result=control(body);else if(path=="/api/annotate"){std::string confidence=body.at("confidence");require(confidence=="observed"||confidence=="hypothesis"||confidence=="verified","Annotation confidence");std::lock_guard lock(store.mutex);sqlite3_stmt* stmt=nullptr;sqlite3_prepare_v2(store.db,"UPDATE packets SET label=?,annotation=?,confidence=? WHERE id=?",-1,&stmt,nullptr);auto label=body.value("label","").substr(0,200),note=body.value("note","").substr(0,4000);sqlite3_bind_text(stmt,1,label.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(stmt,2,note.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(stmt,3,confidence.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_int64(stmt,4,body.at("packet_id"));sqlite3_step(stmt);sqlite3_finalize(stmt);result={{"ok",true}};}else throw std::runtime_error("Unknown API");}else{require(method=="GET","Method unsupported");if(path=="/api/state")result=state();else if(path=="/api/world-view")result=world_view();else if(path=="/api/world-geometry"){std::shared_ptr<const CollisionWorld> snapshot;Vec origin;{std::lock_guard lock(mutex);snapshot=geometry;origin=config.at("spawn").get<Vec>();}for(int i=0;i<3;i++)origin[i]=std::stod(arg(std::array<std::string,3>{"x","y","z"}[i],std::to_string(origin[i])));result=snapshot->geometry(origin,std::stod(arg("radius","20000")),std::stoi(arg("stride","8")),arg("detail","lightweight"));}else if(path=="/api/packets"){int limit=std::clamp(std::stoi(arg("limit","100")),1,500);uint64_t after=std::stoull(arg("after","0"));result=store.query("SELECT * FROM packets WHERE id>"+std::to_string(after)+" ORDER BY id DESC LIMIT "+std::to_string(limit));for(auto& row:result)row["decoded"]=Json::parse(row["decoded"].get<std::string>());}else if(path=="/api/events")result=store.query("SELECT * FROM events ORDER BY id DESC LIMIT 100");else if(path=="/api/connections"){std::lock_guard lock(mutex);result=Json::array();for(auto& [peer,c]:protocol.connections){Json actors;for(auto& [kind,g]:c.actors)actors[kind]=g.json();result.push_back({{"peer",peer},{"id",c.id},{"phase",c.phase},{"selected_character_id",c.selected_character_id},{"selected_character_name",c.selected_character_name},{"actors",actors},{"possession",c.possession},{"initialization",c.initialization_status},{"initialization_error",c.initialization_error},{"initialization_failed",c.initialization_failed},{"speed_sync",c.speed_sync_status},{"speed_synced",c.speed_synced},{"stages",c.stages}});}}else{require(path.find("..") == std::string::npos&&path.find('%')==std::string::npos&&path.find('\\')==std::string::npos,"Invalid asset path");auto file=root/"web"/(path=="/"?"index.html":path.substr(1));auto raw=read_file(file);response.assign(raw.begin(),raw.end());std::string ext=file.extension().string();type=ext==".html"?"text/html; charset=utf-8":ext==".js"?"application/javascript":ext==".css"?"text/css":"application/octet-stream";}}if(type=="application/json")response=result.dump();}catch(const std::exception& e){status=400;response=Json{{"ok",false},{"error",e.what()},{"message",e.what()}}.dump();}std::string h="HTTP/1.1 "+std::to_string(status)+(status==200?" OK":" Bad Request")+"\r\nContent-Type: "+type+"\r\nContent-Length: "+std::to_string(response.size())+"\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nConnection: close\r\n\r\n";send_all(socket,reinterpret_cast<const uint8_t*>(h.data()),h.size());send_all(socket,reinterpret_cast<const uint8_t*>(response.data()),response.size());}
